import re
from collections import Counter
def names(doc):
    return re.findall(r"\b([A-Z][a-z]+(?:[A-Z][a-z]+)+)\b", doc)
cnt = Counter()
perdoc = []
for d in docs:
    perdoc.append(set(names(d)))
for s in perdoc:
    cnt.update(s)
common = set.intersection(*perdoc)
print(len(common))
for k in sorted(common):
    print(k)
